define('ember-flexberry-data/utils/is-embedded', ['exports'], function (exports) {
  'use strict';

  exports['default'] = isEmbedded;

  /**
    @method isEmbedded
    @param {DS.Store} store
    @param {DS.Model} modelType
    @param {String} relationshipName
    @return {Boolean}
  */
  function isEmbedded(store, modelType, relationshipName) {
    var serializerAttrs = store.serializerFor(modelType.modelName).get('attrs');
    return serializerAttrs && serializerAttrs[relationshipName] && (serializerAttrs[relationshipName].embedded && serializerAttrs[relationshipName].embedded === 'always' || serializerAttrs[relationshipName].deserialize && serializerAttrs[relationshipName].deserialize === 'records');
  }
});