define('ember-flexberry/initializers/log', ['exports'], function (exports) {
  'use strict';

  exports.initialize = initialize;

  /**
    @module ember-flexberry
  */

  /**
    Injects a {{#crossLink "LogService"}}log service{{/crossLink}} into current application
    components, controllers, models, routes, and views.
  
    @for ApplicationInitializer
    @method log.initialize
    @param {<a href="http://emberjs.com/api/classes/Ember.Application.html">Ember.Application</a>} application Ember application.
  */

  function initialize(application) {
    ['component', 'controller', 'route', 'view'].forEach(function (type) {
      application.inject(type, 'logService', 'service:log');
    });
  }

  exports['default'] = {
    name: 'log',
    initialize: initialize
  };
});