define("ember-flexberry/utils/get-attr-locale-key", ["exports"], function (exports) {
  "use strict";

  exports["default"] = getAttrLocaleKey;

  function getAttrLocaleKey(mainModelName, projectionName, bindingPath, nameRelationship) {
    var newBindingPath = bindingPath;
    if (nameRelationship) {
      newBindingPath = nameRelationship + "." + bindingPath;
    }

    return "models." + mainModelName + ".projections." + projectionName + "." + newBindingPath + ".__caption__";
  }
});