define('ember-flexberry-data/utils/enum-functions', ['exports', 'ember'], function (exports, _ember) {
  'use strict';

  exports.createEnum = createEnum;
  exports.inverseEnum = inverseEnum;
  exports.enumCaptions = enumCaptions;

  /**
    @module ember-flexberry-data
  */

  /**
    Returns friezed object without prototype with own properties of parameter.
  
    @function createEnum
    @param {Object|Array} dictionary
    @return {Object}
  */

  function createEnum(dictionary) {
    var local = {};
    if (_ember['default'].isArray(dictionary)) {
      dictionary.forEach(function (element) {
        return local[element] = element;
      });
    } else {
      local = dictionary;
    }

    return Object.freeze(_ember['default'].merge(Object.create(null), local));
  }

  /**
    Returns friezed inversed object without prototype.
  
    @function inverseEnum
    @param {Object} dictionary
    @return {Object}
  */

  function inverseEnum(dictionary) {
    var inverse = {};
    for (var key in dictionary) {
      inverse[dictionary[key]] = key;
    }

    return createEnum(inverse);
  }

  /**
    Returns object without null values.
  
    @function enumCaptions
    @param {Object} dictionary
    @return {Object}
  */

  function enumCaptions(dictionary) {
    var captions = {};

    for (var key in dictionary) {
      if (dictionary[key] === null) {
        captions[key] = '';
      } else {
        captions[key] = dictionary[key];
      }
    }

    return captions;
  }
});