define('ember-flexberry/instance-initializers/default-user-settings', ['exports'], function (exports) {
  'use strict';

  exports.initialize = initialize;

  /**
    @module ember-flexberry
   */

  /**
   * Registry options for default user settings
   *
   * @param applicationInstance
   */

  function initialize(applicationInstance) {

    applicationInstance.registerOptionsForType('default-user-setting', { instantiate: false });
  }

  exports['default'] = {
    name: 'default-user-settings',
    initialize: initialize
  };
});