define('ember-flexberry-data/initializers/offline-globals', ['exports'], function (exports) {
  'use strict';

  exports.initialize = initialize;

  function initialize(application) {
    //Inject OfflieGlobalsService onto factories of specified types.
    ['store:local', 'controller', 'component', 'model', 'route', 'view'].forEach(function (type) {
      application.inject(type, 'offlineGlobals', 'service:offline-globals');
    });
  }

  exports['default'] = {
    name: 'offline-globals',
    initialize: initialize
  };
});