define('ember-flexberry/utils/get-projection-by-name', ['exports', 'ember'], function (exports, _ember) {
  'use strict';

  exports['default'] = getProjectionByName;

  /**
    @module ember-flexberry
  */

  /**
    Used for getting projection object by projection name.
  
    @method getProjectionByName
    @param {Object} projectionName Projection name.
    @param {String} modelName Model Name.
    @param {Object} store
    @return {Object} Projection by name.
  */
  function getProjectionByName(projectionName, modelName, store) {
    _ember['default'].assert('For define projection by name, model name is required.', modelName);
    _ember['default'].assert('For define projection by name, store is required.', store);
    var modelConstructor = store.modelFor(modelName);
    _ember['default'].assert('Model with name \'' + modelName + '\' is not found.', modelConstructor);

    return _ember['default'].get(modelConstructor, 'projections.' + projectionName);
  }
});