define('ember-flexberry-data/utils/is-uuid', ['exports'], function (exports) {
  'use strict';

  exports['default'] = isUUID;

  /**
    @method isUUID
    @param {DS.Store} uuid
    @return {Boolean}
  */
  function isUUID(uuid) {
    var uuidStr = '' + uuid;
    uuidStr = uuidStr.match('^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$');
    if (uuidStr === null) {
      return false;
    }

    return true;
  }
});